# Own-wording magic items of Griffon's Saddlebag, Book 1 (2024), chunk E: variants that chunks A to D skipped. Row shape as tghp_item.py.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

add("Fanfare Ammunition", "Weapon", "Common", 0, "Trick ammunition meant to distract. On a ranged hit it deals no damage and is destroyed. A noise of your choice, from a whisper to a scream, sounds at the impact point. A creature that hears it can tell it is an illusion with a DC 10 Intelligence (Investigation) check.")

add("Festerwood Masher", "Weapon", "Very Rare", 1, "A Maul or Warhammer of corroded wood with +2 to attack and damage rolls. It has 3 charges and regains all at dusk. When you hit, spend 1 charge to splash acid. A Large or smaller target takes a cumulative -1 penalty to AC for 1 minute. A Huge target takes the penalty only from the second splash, and a Gargantuan one from the third, within 1 minute. When the hammer hits an affected target, it takes an extra 1d4 Acid damage per -1 of AC penalty.", fx={"atk": 2, "dmg": 2}, base=["Maul", "Warhammer"], ch=[3, "all", "dusk"])

add("Forgemaster's Might", "Weapon", "Legendary", 1, "A Maul or Warhammer that needs Strength 17 or higher to wield. +2 to attack and damage rolls. As a Bonus Action, speak \"light the forge\" to wreathe the head in flames: Bright Light in 20 ft and Dim Light for 20 ft more, an extra 1d8 Fire damage on a hit, and it ignores Fire Resistance. Speak \"quench\" as a Bonus Action to end it, or drop or stow the hammer.\n**Smith's Blessing.** Cast Creation (level 6 version) or Fabricate as a Magic action, once each until the next dawn. Creation's materials can feed Fabricate. You know Mending while attuned, and it can repair a break or tear of up to 5 ft. You have Advantage on Smith's Tools checks to craft or repair an object using the hammer head as the anvil.\n**Iron Raze.** It deals an extra 2d8 Bludgeoning damage to Constructs and structures.", fx={"atk": 2, "dmg": 2}, base=["Maul", "Warhammer"])
SP["Forgemaster's Might"] = {"sp": [["Creation", 1], ["Fabricate", 1]]}

add("Galepierce Weapon", "Weapon", "Uncommon", 0, "A Piercing weapon with the Thrown property, tempered to glide on wind. The normal and long ranges of its Thrown property double. Ranged attacks with it ignore air-based hindrances such as fog and strong winds, so they carry no Disadvantage or automatic miss from those causes.")

add("Healing Ammunition", "Weapon", "Uncommon", 0, "Ammunition made by elder nature clerics. A hit deals no damage. If the target is a creature other than you, it regains 2d4 Hit Points plus your Dexterity and Wisdom modifiers (minimum +1). You have Advantage on the attack roll against an ally. The ammunition dissolves into healing magic once it hits.")

add("Memento of the Shapeless", "Weapon", "Legendary", 1, "A Melee weapon forged from a mimic's remains. +2 to attack and damage rolls. As a Bonus Action, speak a command word to reshape it into any Melee weapon you are proficient with that lacks the Heavy and Reach properties.\n**Grapple.** When you hit, you can try to grapple the target at no action cost. It must succeed on a DC 13 Strength save or have the Grappled condition. While it lasts, you cannot attack or grapple another creature with the weapon. Releasing the weapon ends the condition.\n**Pseudopod.** As a Magic action, make a melee attack against a creature within 30 ft, ignoring Half Cover and Three-Quarters Cover. It deals 6d8 Bludgeoning damage on a hit. If you try to grapple with it, the save DC is 15. On a failure the target is pulled up to 15 ft toward you, or up to 30 ft and kept Grappled if it fails by 5 or more. After 12 hours you can use this again.\n**Limb Replacement.** If you miss an arm or forearm, you can graft the weapon in its place. You add your Proficiency Bonus to Strength (Athletics) checks with that limb, doubled if you are already proficient in Athletics. You can reshape the limb into the weapon or back at will.", fx={"atk": 2, "dmg": 2})

add("Moonswaddled Armor", "Armor", "Rare", 0, "Light armor that gives +1 AC while worn between dusk and dawn. When you take a Short Rest after dusk, each Hit Point Die you spend restores its highest possible roll.")

add("Phoenix Ammunition", "Weapon", "Rare", 0, "An Arrow or Bolt fletched with phoenix feathers, bound to a Quiver or Crossbow Bolt Case. +1 to attack and damage rolls. A hit deals Fire damage instead of Piercing. At the start of your next turn it turns to ash and reappears in its container.\nAs a Bonus Action before firing, speak a command word to ignite it. If fired that turn, it deals an extra 1d6 Fire damage on a hit and turns to ash at once, or before reaching a target more than 30 ft away.\nThe container holds up to ten other Arrows or Bolts but only one Phoenix piece. If it is destroyed, it returns after 24 hours unless it was nonmagical when destroyed, such as inside an Antimagic Field.", fx={"atk": 1, "dmg": 1})

add("Runic Ammunition", "Weapon", "Rare", 0, "Ammunition etched with runes that clash with spellcasting. +1 to attack and damage rolls. A concentrating creature it hits has Disadvantage on the save to keep Concentration. After it hits, it becomes nonmagical.", fx={"atk": 1, "dmg": 1})
